// ═══════════════════════════════════════
// VALIDATION games.csv
// Applique toutes les règles de l'Algo 1
// ═══════════════════════════════════════
const fs = require('fs');
const path = require('path');

const DATA_DIR = process.env.NBA_DATA_DIR || '/data/nba';
const filePath = path.join(DATA_DIR, 'games.csv');

if (!fs.existsSync(filePath)) {
  throw new Error(`games.csv introuvable dans ${DATA_DIR}`);
}

const content = fs.readFileSync(filePath, 'utf8');
const lines = content.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));

const rows = [];
const erreurs = [];
const seenIds = new Set();

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',');
  if (vals.length < headers.length) continue;

  const row = {};
  headers.forEach((h, idx) => {
    row[h] = vals[idx] ? vals[idx].trim().replace(/"/g, '') : null;
  });

  const gameId = parseInt(row['GAME_ID']);
  const homePts = row['PTS_home'] ? parseFloat(row['PTS_home']) : null;
  const awayPts = row['PTS_away'] ? parseFloat(row['PTS_away']) : null;
  const homeId  = parseInt(row['HOME_TEAM_ID']);
  const awayId  = parseInt(row['VISITOR_TEAM_ID']);
  const season  = parseInt(row['SEASON']);

  // Règle 1 : GAME_ID non-null
  if (isNaN(gameId)) { erreurs.push(`Ligne ${i}: GAME_ID null`); continue; }

  // Règle 2 : pas de doublon
  if (seenIds.has(gameId)) { continue; }
  seenIds.add(gameId);

  // Règle 3 : home ≠ visitor
  if (homeId === awayId) { erreurs.push(`Ligne ${i}: HOME=VISITOR game ${gameId}`); continue; }

  // Règle 4 : scores valides
  if (homePts !== null && (homePts < 0 || homePts > 200)) row['PTS_home'] = null;
  if (awayPts !== null && (awayPts < 0 || awayPts > 200)) row['PTS_away'] = null;

  // Règle 5 : saison valide
  if (season < 1990 || season > 2030) { erreurs.push(`Ligne ${i}: saison hors bornes ${season}`); continue; }

  rows.push(row);
}

return [{
  json: {
    label: 'games',
    rows: rows,
    count: rows.length,
    erreurs: erreurs,
    nb_erreurs: erreurs.length
  }
}];

const fs = require('fs');
const path = require('path');

const DATA_DIR = process.env.NBA_DATA_DIR || '/data/nba';
const filePath = path.join(DATA_DIR, 'games_details.csv');

if (!fs.existsSync(filePath)) {
  throw new Error(`games_details.csv introuvable dans ${DATA_DIR}`);
}

const content = fs.readFileSync(filePath, 'utf8');
const lines = content.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));

const rows = [];
const erreurs = [];
const seenKeys = new Set();

function parseMinToSeconds(minStr) {
  if (!minStr || minStr === 'null') return null;
  const parts = minStr.split(':');
  if (parts.length !== 2) return null;
  const total = parseInt(parts[0]) * 60 + parseInt(parts[1]);
  return (total >= 0 && total <= 3180) ? total : null;
}

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',');
  if (vals.length < headers.length) continue;

  const row = {};
  headers.forEach((h, idx) => {
    const v = vals[idx] ? vals[idx].trim().replace(/"/g, '') : null;
    row[h] = (v === '' || v === 'nan' || v === 'NaN') ? null : v;
  });

  const gameId   = parseInt(row['GAME_ID']);
  const playerId = parseInt(row['PLAYER_ID']);
  if (isNaN(gameId) || isNaN(playerId)) continue;

  const key = `${gameId}_${playerId}`;
  if (seenKeys.has(key)) continue;
  seenKeys.add(key);

  const fgm = row['FGM'] ? parseFloat(row['FGM']) : null;
  const fga = row['FGA'] ? parseFloat(row['FGA']) : null;
  const fg3m= row['FG3M']? parseFloat(row['FG3M']): null;
  const fg3a= row['FG3A']? parseFloat(row['FG3A']): null;
  const ftm = row['FTM'] ? parseFloat(row['FTM']) : null;
  const fta = row['FTA'] ? parseFloat(row['FTA']) : null;
  const pts = row['PTS'] ? parseFloat(row['PTS']) : null;

  // Validation uniquement pour les joueurs ayant joué
  if (row['MIN'] !== null) {
    if (fgm !== null && fga !== null && fgm > fga) { erreurs.push(`${key}: FGM>FGA`); continue; }
    if (fg3m!== null && fg3a!== null && fg3m > fg3a){ erreurs.push(`${key}: FG3M>FG3A`); continue; }
    if (fg3a!== null && fga !== null && fg3a > fga) { erreurs.push(`${key}: FG3A>FGA`);  continue; }
    if (ftm !== null && fta !== null && ftm > fta)  { erreurs.push(`${key}: FTM>FTA`);  continue; }
    if (fgm !== null && fg3m!== null && ftm !== null && pts !== null) {
      const calcPts = (fgm - fg3m) * 2 + fg3m * 3 + ftm;
      if (Math.abs(calcPts - pts) > 1) { erreurs.push(`${key}: pts incohérents`); continue; }
    }
  }

  row['MIN_SECONDES'] = parseMinToSeconds(row['MIN']);
  row['a_joue'] = row['MIN'] !== null;
  rows.push(row);
}

return [{
  json: {
    label: 'details',
    rows: rows,
    count: rows.length,
    erreurs: erreurs,
    nb_erreurs: erreurs.length
  }
}];

const fs = require('fs');
const path = require('path');

const DATA_DIR = process.env.NBA_DATA_DIR || '/data/nba';
const filePath = path.join(DATA_DIR, 'players.csv');

const content = fs.readFileSync(filePath, 'utf8');
const lines = content.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));

const rows = [];
const erreurs = [];
const seen = new Set();

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',');
  const row = {};
  headers.forEach((h, idx) => {
    const v = vals[idx] ? vals[idx].trim().replace(/"/g, '') : null;
    row[h] = (v === '' || v === 'nan') ? null : v;
  });

  const pid    = parseInt(row['PLAYER_ID']);
  const tid    = parseInt(row['TEAM_ID']);
  const season = parseInt(row['SEASON']);
  const name   = row['PLAYER_NAME'];

  if (isNaN(pid) || isNaN(tid) || !name || name.trim() === '') continue;
  if (season < 1990 || season > 2030) continue;

  const key = `${pid}_${tid}_${season}`;
  if (seen.has(key)) continue;
  seen.add(key);

  rows.push(row);
}

return [{
  json: {
    label: 'players',
    rows: rows,
    count: rows.length,
    erreurs: erreurs,
    nb_erreurs: erreurs.length
  }
}];

const fs = require('fs');
const path = require('path');

const DATA_DIR = process.env.NBA_DATA_DIR || '/data/nba';
const filePath = path.join(DATA_DIR, 'ranking.csv');

const content = fs.readFileSync(filePath, 'utf8');
const lines = content.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));

const rows = [];
const erreurs = [];
const seen = new Set();

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',');
  const row = {};
  headers.forEach((h, idx) => {
    const v = vals[idx] ? vals[idx].trim().replace(/"/g, '') : null;
    row[h] = (v === '' || v === 'nan') ? null : v;
  });

  const tid  = parseInt(row['TEAM_ID']);
  const date = row['STANDINGSDATE'];
  const conf = row['CONFERENCE'];
  const W = parseInt(row['W']);
  const L = parseInt(row['L']);
  const G = parseInt(row['G']);

  if (isNaN(tid) || !date) continue;
  if (!['East','West'].includes(conf)) continue;
  if (!isNaN(W) && !isNaN(L) && !isNaN(G) && (W + L) !== G) {
    row['G'] = String(W + L); // correction
  }

  const key = `${tid}_${date}`;
  if (seen.has(key)) continue;
  seen.add(key);

  rows.push(row);
}

return [{
  json: {
    label: 'ranking',
    rows: rows,
    count: rows.length,
    erreurs: erreurs,
    nb_erreurs: erreurs.length
  }
}];

const items = $input.all();
const rapportErreurs = [];
let bloquant = false;

for (const item of items) {
  const d = item.json;
  if (!d.label) continue;
  rapportErreurs.push({
    fichier: d.label,
    lignes_valides: d.count,
    nb_erreurs: d.nb_erreurs
  });
  // Bloquer si trop d'erreurs (> 5% des lignes)
  if (d.nb_erreurs > d.count * 0.05) {
    bloquant = true;
  }
}

if (bloquant) {
  throw new Error('Trop d erreurs dans les CSV — pipeline bloqué. Vérifier les logs.');
}

return [{ json: { validation_ok: true, rapport: rapportErreurs } }];

