CREATE CONSTRAINT contrainte_saison_id     IF NOT EXISTS FOR (n:Saison)      REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT contrainte_equipe_id     IF NOT EXISTS FOR (n:Equipe)      REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT contrainte_joueur_id     IF NOT EXISTS FOR (n:Joueur)      REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT contrainte_match_id      IF NOT EXISTS FOR (n:Match)       REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT contrainte_perf_id       IF NOT EXISTS FOR (n:Performance) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT contrainte_classement_id IF NOT EXISTS FOR (n:Classement)  REQUIRE n.id IS UNIQUE;
CREATE INDEX idx_match_date     IF NOT EXISTS FOR (n:Match)      ON (n.date_est);
CREATE INDEX idx_classement_date IF NOT EXISTS FOR (n:Classement) ON (n.date);
RETURN 'contraintes_ok' AS statut

// Relations Saison→Match
UNWIND $saison_match AS row
MATCH (s:Saison {id: row.saison_id})
MATCH (m:Match  {id: row.match_id})
MERGE (s)-[:CONTIENT]->(m);

// Relations Equipe→Match (domicile)
UNWIND $equipe_match_dom AS row
MATCH (e:Equipe {id: row.equipe_id})
MATCH (m:Match  {id: row.match_id})
MERGE (e)-[r:DISPUTE]->(m)
ON CREATE SET r.score = row.score, r.resultat = row.resultat;

// Relations Equipe→Match (visiteur)
UNWIND $equipe_match_vis AS row
MATCH (e:Equipe {id: row.equipe_id})
MATCH (m:Match  {id: row.match_id})
MERGE (e)-[r:VISITE]->(m)
ON CREATE SET r.score = row.score, r.resultat = row.resultat;

RETURN 'relations_match_ok' AS statut

