  `Joueurs: ${d.nb_joueurs} | Équipes: ${d.nb_equipes} | Matchs: ${d.nb_matchs} | Performances: ${d.nb_perfs}`,
  `Statut: ${d.statut_graphe}`,
  `Exécuté: ${new Date().toISOString()}`
].join('\n');
console.log(msg);
return [{ json: { message: msg, statut: 'SUCCÈS', timestamp: new Date().toISOString(), ...d } }];

const d = $input.first().json;
const problemes = [];
if (d.perfs_isolees   > 0) problemes.push(`${d.perfs_isolees} performances isolées`);
if (d.matchs_isoles   > 0) problemes.push(`${d.matchs_isoles} matchs isolés`);
if (d.fg_invalides    > 0) problemes.push(`${d.fg_invalides} stats FG invalides`);
if (d.classements_invalides > 0) problemes.push(`${d.classements_invalides} classements incohérents`);
const msg = [
  '❌ NBA Neo4j — Graphe DÉGRADÉ',
  'Problèmes: ' + problemes.join(', '),
  'Action: consulter cypher/repair.cypher',
  `Exécuté: ${new Date().toISOString()}`
].join('\n');
console.error(msg);
return [{ json: { message: msg, statut: 'DÉGRADÉ', problemes, timestamp: new Date().toISOString() } }];
